x = 1:100;

% a.
y = x.^3 + 4 * x - 15;
plot(x,y) %[output:0b92dce6]
% b.
y = sin(x) + sin(2*x) + sin(4*x);
plot(x,y) %[output:30c06cde]
% c.
y = exp(-1./x) .* cos(x);
plot(x,y) %[output:21d147e9]
% d.
y = cos(x) + cos(3*x) + cos(5*x);
plot(x,y) %[output:4ef2c803]
% e.
y = tan(x) ./ x;
plot(x,y) %[output:2aaea54e]
% f.
y = (1 + 5./x - 3./(x.^4)) .* (1 <= x & x < 50) + sqrt(x) .* (50 <= x & x <= 100);
plot(x,y) %[output:95e95722]

